package com.trevasq.qguard.service; import com.trevasq.qguard.config.AppProperties; import com.trevasq.qguard.domain.Booking; import jakarta.mail.internet.MimeMessage; import org.springframework.mail.javamail.*; import org.springframework.stereotype.Service;
@Service public class NotificationService { private final JavaMailSender mail; private final CalendarService calendar; private final AppProperties p; public NotificationService(JavaMailSender m,CalendarService c,AppProperties p){mail=m;calendar=c;this.p=p;} public void confirmation(Booking b,String url){try{MimeMessage msg=mail.createMimeMessage();MimeMessageHelper h=new MimeMessageHelper(msg,true);h.setFrom(p.sender());h.setTo(b.getEmail());h.setSubject("Your QGuard demo is confirmed");h.setText("Hello "+b.getName()+",\n\nYour QGuard demo is confirmed for "+b.getStartsAt()+" UTC. Manage it securely: "+url);h.addAttachment("qguard-demo.ics",new org.springframework.core.io.ByteArrayResource(calendar.invitation(b).getBytes()),"text/calendar");mail.send(msg);}catch(Exception e){throw new NotificationException();}} public static class NotificationException extends RuntimeException{} }
